119	impl<'a> WorkspacePackageSpecifier<'a> {
120	    fn new(version: &'a str) -> Option<Self> {
121	        let version = version.strip_prefix("workspace:")?;
122	        match version.rsplit_once('@') {
123	            Some((name, "*")) | Some((name, "^")) | Some((name, "~")) => Some(Self::Alias(name)),
124	            // No indication of different name for the package
125	            // We want to capture specifiers that have type "directory" by npa which boils down to
126	            // checking for slashes: https://github.com/pnpm/npm-package-arg/blob/main/npa.js#L79
127	            Some(_) | None if version.contains('/') => {
128	                RelativeUnixPath::new(version).ok().map(Self::Path)
129	            }
130	            Some(_) | None => None,
131	        }
132	    }
